#nullable enable // autogenerated

using System.Collections.Generic;
using PVZEngine.Tools.Unity;

namespace MVZ2.Resources
{
    public class ResourceResolver<TKey, TResource>
    {
        public ResourceResolver(bool silent = false)
        {
            Silent = silent;
        }
        public void AddProvider(IResourceProvider<TKey, TResource> db)
        {
            providers.Add(db);
        }
        public bool RemoveProvider(IResourceProvider<TKey, TResource> db)
        {
            return providers.Remove(db);
        }
        public void SortProviders()
        {
            providers.Sort(comparer);
        }
        public void ClearProviders()
        {
            providers.Clear();
        }

        /// <summary>
        /// 解析Sprite。
        /// </summary>
        public TResource? Resolve(TKey key, ResourceContext context)
        {
            List<TKey> candidateKeys = BuildCandidateKeys(key, context);

            foreach (IResourceProvider<TKey, TResource> db in providers)
            {
                foreach (TKey candidate in candidateKeys)
                {
                    if (db.TryGet(candidate, out var sprite))
                    {
                        return sprite;
                    }
                }
            }

            if (!Silent)
            {
                Log.LogWarning($"Resource not found: {key}");
            }
            return default;
        }

        protected virtual List<TKey> BuildCandidateKeys(TKey key, ResourceContext context)
        {
            var list = new List<TKey>();
            list.Add(key);
            return list;
        }

        public bool Silent { get; }
        private readonly List<IResourceProvider<TKey, TResource>> providers = new();
        private readonly Comparer comparer = new();

        private class Comparer : IComparer<IResourceProvider<TKey, TResource>>
        {
            public int Compare(IResourceProvider<TKey, TResource> x, IResourceProvider<TKey, TResource> y)
            {
                return y.Priority.CompareTo(x.Priority);
            }
        }
    }
}
